mapper.select:
SELECT language, active, CAST(normalized_json AS CHAR) AS normalizedJson
FROM expedia_property_content
WHERE property_id = #{propertyId}

mapper.insert:
INSERT INTO hotel_extend (
    hotel_id, room_id, language, check_in, check_out, instructions, fees, policies, descriptions
) VALUES (
    #{hotelId}, '', #{language}, #{checkIn}, #{checkOut}, #{instructions}, #{fees}, #{policies}, #{descriptions}
)
ON DUPLICATE KEY UPDATE
    check_in = VALUES(check_in), check_out = VALUES(check_out),
    instructions = VALUES(instructions), fees = VALUES(fees),
    policies = VALUES(policies), descriptions = VALUES(descriptions), del = 0
